UPDATE sources SET url = 'https://www.tuwien.at/en/research/tuw-doctoral-center/doctoral-colleges', title = 'Doctoral Colleges | TU Wien (official)', accessed_at = now(), is_official = true, is_verified = true WHERE id = 2633;
